/* Exportación Word DOCX real, sin peticiones de red y con las palomas integradas. */
(() => {
  'use strict';
  const encoder = new TextEncoder();
  const xmlEsc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[ch]));
  const textBytes = text => encoder.encode(String(text));
  const le16 = n => [n & 255, (n >>> 8) & 255];
  const le32 = n => [n & 255, (n >>> 8) & 255, (n >>> 16) & 255, (n >>> 24) & 255];
  const crcTable = Array.from({length: 256}, (_, i) => {
    let c = i;
    for (let j = 0; j < 8; j++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    return c >>> 0;
  });
  const crc32 = data => {
    let crc = 0xffffffff;
    for (const b of data) crc = crcTable[(crc ^ b) & 255] ^ (crc >>> 8);
    return (crc ^ 0xffffffff) >>> 0;
  };
  function packageZip(files) {
    // ZIP STORE: .docx completamente compatible y funciona incluso sin internet.
    const parts = [], central = [];
    let position = 0;
    const push = bytes => { parts.push(bytes); position += bytes.length; };
    for (const file of files) {
      const name = textBytes(file.name);
      const data = file.data instanceof Uint8Array ? file.data : textBytes(file.data);
      const crc = crc32(data), start = position;
      push(Uint8Array.from([...le32(0x04034b50), ...le16(20), ...le16(0x0800), ...le16(0), ...le16(0), ...le16(0), ...le32(crc), ...le32(data.length), ...le32(data.length), ...le16(name.length), ...le16(0)]));
      push(name); push(data);
      central.push(Uint8Array.from([...le32(0x02014b50), ...le16(20), ...le16(20), ...le16(0x0800), ...le16(0), ...le16(0), ...le16(0), ...le32(crc), ...le32(data.length), ...le32(data.length), ...le16(name.length), ...le16(0), ...le16(0), ...le16(0), ...le16(0), ...le32(0), ...le32(start)]), name);
    }
    const centralAt = position;
    for (const part of central) push(part);
    const centralSize = position - centralAt;
    push(Uint8Array.from([...le32(0x06054b50), ...le16(0), ...le16(0), ...le16(files.length), ...le16(files.length), ...le32(centralSize), ...le32(centralAt), ...le16(0)]));
    return new Blob(parts, {type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});
  }
  function run(text, {color='202D40', bold=false, size=25}={}) {
    if (!text) return '';
    return `<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:color w:val="${color}"/>${bold?'<w:b/>':''}<w:sz w:val="${size}"/></w:rPr><w:t xml:space="preserve">${xmlEsc(text)}</w:t></w:r>`;
  }
  function styleRuns(raw, baseColor, baseBold, fontSize) {
    // Convierte tokens **negrita** y {#RRGGBB|color} en formato nativo Word.
    const pattern = /(\{#[0-9a-fA-F]{6}\|[^}\n]*\}|\*\*[^*\n]+\*\*)/g;
    let result = '', last=0, match;
    while ((match=pattern.exec(raw)) !== null) {
      result += run(raw.slice(last, match.index), {color:baseColor,bold:baseBold,size:fontSize});
      const token=match[0];
      if (token.startsWith('{#')) {
        const marker = token.indexOf('|'), color=token.slice(2,marker).toUpperCase();
        const content=token.slice(marker+1,-1);
        const boldPattern=/\*\*([^*\n]+)\*\*/g;
        let lastBold=0, b;
        while ((b=boldPattern.exec(content)) !== null) {
          result += run(content.slice(lastBold,b.index), {color,bold:baseBold,size:fontSize});
          result += run(b[1], {color,bold:true,size:fontSize});
          lastBold=boldPattern.lastIndex;
        }
        result += run(content.slice(lastBold), {color,bold:baseBold,size:fontSize});
      } else result += run(token.slice(2,-2), {color:baseColor,bold:true,size:fontSize});
      last=pattern.lastIndex;
    }
    return result + run(raw.slice(last),{color:baseColor,bold:baseBold,size:fontSize});
  }
  function paragraph(runs, {before=0, after=80, spacing=360, keepNext=false}={}) {
    return `<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="${before}" w:after="${after}" w:line="${spacing}" w:lineRule="auto"/>${keepNext?'<w:keepNext/>':''}</w:pPr>${runs}</w:p>`;
  }
  function inlineImage(id, flip=false) {
    const w=1220000,h=1182000; // 128 x 124 px; palomas grandes, como la vista previa.
    return `<w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"><wp:extent cx="${w}" cy="${h}"/><wp:docPr id="${id}" name="Paloma ${id}" descr="Paloma blanca con rama verde"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="${id}" name="Paloma.png"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm${flip?' flipH="1"':''}><a:off x="0" y="0"/><a:ext cx="${w}" cy="${h}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r>`;
  }
  function dovesTable() {
    const cell = (align, id, flip) => `<w:tc><w:tcPr><w:tcW w:w="4500" w:type="dxa"/><w:vAlign w:val="top"/></w:tcPr><w:p><w:pPr><w:jc w:val="${align}"/><w:spacing w:after="0"/></w:pPr>${inlineImage(id, flip)}</w:p></w:tc>`;
    return `<w:tbl><w:tblPr><w:tblW w:w="9000" w:type="dxa"/><w:tblBorders><w:top w:val="nil"/><w:bottom w:val="nil"/><w:left w:val="nil"/><w:right w:val="nil"/><w:insideH w:val="nil"/><w:insideV w:val="nil"/></w:tblBorders></w:tblPr><w:tblGrid><w:gridCol w:w="4500"/><w:gridCol w:w="4500"/></w:tblGrid><w:tr>${cell('left',1,false)}${cell('right',2,true)}</w:tr></w:tbl>`;
  }
  // Palomas incluidas dentro del exportador: cero llamadas a fetch y funciona offline.
  const DOVE_PNG_BASE64 = '';
  function readImage() {
    const binary = atob(DOVE_PNG_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i=0; i<binary.length; i++) bytes[i]=binary.charCodeAt(i);
    return bytes;
  }
  function download(blob, name) {
    const link=document.createElement('a');
    const url=URL.createObjectURL(blob);
    link.href=url; link.download=name;
    document.body.appendChild(link); link.click(); link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),5000);
  }
  async function exportLyricsDocx({title, text, artist='', normalizer, headingClass, visibleArtist, src='paloma.png', save=true}) {
    title=String(title||'CANCIÓN').trim()||'CANCIÓN';
    text=String(text||'');
    artist=visibleArtist ? visibleArtist(artist) : String(artist||'');
    if (!text.trim()) throw new Error('No hay letra para descargar.');
    const dove=readImage();
    const normalized=normalizer ? normalizer(text) : text.replace(/\r\n?/g,'\n');
    const lines=normalized.replace(/\r\n?/g,'\n').split('\n');
    const titleRun=run(title.toLocaleUpperCase('es'),{color:'355FA1',bold:true,size:37});
    const authorRun=artist ? paragraph(run(artist,{color:'40648E',bold:true,size:25}),{after:340,spacing:300}):'';
    const body=lines.map(line=>{
      const plain=line.replace(/\*\*([^*]+)\*\*/g,'$1').replace(/\{#[0-9a-fA-F]{6}\|([^}\n]*)\}/g,'$1').trim();
      const kind=headingClass ? headingClass(plain) : '';
      const color=kind === 'coro' ? 'B91C1C' : kind ? '173B77' : '253044';
      return paragraph(styleRuns(line,color,!!kind,kind?26:25),{before:kind?260:0,after:line.trim()?70:130,spacing:350,keepNext:!!kind});
    }).join('');
    const document=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>${dovesTable()}${paragraph(titleRun,{before:30,after:100,spacing:390})}${authorRun}${body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="720" w:right="1100" w:bottom="900" w:left="1100" w:header="360" w:footer="360" w:gutter="0"/></w:sectPr></w:body></w:document>`;
    const files=[
      {name:'[Content_Types].xml', data:`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`},
      {name:'_rels/.rels', data:`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`},
      {name:'word/_rels/document.xml.rels', data:`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/paloma.png"/></Relationships>`},
      {name:'word/document.xml', data:document},
      {name:'word/media/paloma.png', data:dove}
    ];
    const blob=packageZip(files);
    if(save) download(blob,title.replace(/[\\/:*?"<>|]/g,'').trim()+'_PALOMAS_OFFLINE_V8.docx');
    return blob;
  }
  globalThis.exportLyricsDocx = exportLyricsDocx;
})();
